"use strict";const POWERUP_TYPES={TRIPLE:{id:"triple",name:"Triple",duration:1e4,color:"#22d3ee",icon:"\u26A1"},ROCKET:{id:"rocket",name:"Rocket",duration:0,color:"#f59e0b",icon:"\u{1F680}"},SHIELD:{id:"shield",name:"Shield",duration:1e4,color:"#34d399",icon:"\u{1F6E1}"},FREEZE:{id:"freeze",name:"Freeze",duration:8e3,color:"#a78bfa",icon:"\u2744"},LIFE:{id:"life",name:"Life",duration:0,color:"#ef4444",icon:"\u2764"}},POWERUP_SPAWN_SCORE=70,POWERUP_LIFE_SCORE=150,POWERUP_LIFE_CHANCE=.12,POWERUP_REGULAR_CHANCE=.25,POWERUP_HP=7;class PowerUp{constructor(i,e,t){this.x=i,this.y=e,this.type=t,this.radius=20,this.active=!0,this.speed=60,this.angle=Math.PI/2,this.hp=POWERUP_HP}update(i,e){const t=e?.5:1;this.y+=Math.sin(this.angle)*this.speed*t*i}draw(i){i.save(),i.globalAlpha=.4,i.fillStyle=this.type.color,i.strokeStyle=this.type.color,i.lineWidth=2,i.beginPath(),i.arc(this.x,this.y,this.radius,0,Math.PI*2),i.fill(),i.stroke(),i.globalAlpha=1,i.font="16px system-ui",i.textAlign="center",i.textBaseline="middle",i.fillText(this.type.icon,this.x,this.y),i.restore()}}class PowerUpManager{constructor(){this.powerups=[],this.activePowerUps={},this.lastSpawnScore=0}update(i,e){for(let t=this.powerups.length-1;t>=0;t--)this.powerups[t].update(i,e),this.powerups[t].y>window.innerHeight+50&&this.powerups.splice(t,1)}draw(i){for(const e of this.powerups)e.draw(i)}checkCollision(i,e,t){for(let s=this.powerups.length-1;s>=0;s--){const o=this.powerups[s],n=i-o.x,r=e-o.y;if(Math.sqrt(n*n+r*r)<t+o.radius)return this.powerups.splice(s,1),o.type}return null}trySpawnPowerUp(i){const e=Math.floor(i/POWERUP_SPAWN_SCORE),t=Math.floor(this.lastSpawnScore/POWERUP_SPAWN_SCORE);if(e>t)if(this.lastSpawnScore=i,i>=POWERUP_LIFE_SCORE&&!this.activePowerUps.life){if(Math.random()<POWERUP_LIFE_CHANCE){this.spawn(POWERUP_TYPES.LIFE);return}this.spawnRandom()}else Math.random()<POWERUP_REGULAR_CHANCE&&this.spawnRandom()}spawnRandom(){const i=[POWERUP_TYPES.TRIPLE,POWERUP_TYPES.ROCKET,POWERUP_TYPES.SHIELD,POWERUP_TYPES.FREEZE],e=i[Math.floor(Math.random()*i.length)];this.spawn(e)}spawn(i){const e=Math.random()*(window.innerWidth-100)+50,t=-30,s=new PowerUp(e,t,i);this.powerups.push(s)}activate(i){if(i.id==="life"){this.activePowerUps.life={type:i,remaining:1/0,maxDuration:1/0};return}this.activePowerUps[i.id]?(this.activePowerUps[i.id].remaining=i.duration,this.activePowerUps[i.id].maxDuration=i.duration):this.activePowerUps[i.id]={type:i,remaining:i.duration,startTime:Date.now(),maxDuration:i.duration}}activateByShooting(i){for(let e=this.powerups.length-1;e>=0;e--){const t=this.powerups[e];for(let s=i.length-1;s>=0;s--){const o=i[s],n=o.x-t.x,r=o.y-t.y;if(Math.sqrt(n*n+r*r)<o.radius+t.radius){if(t.hp--,i.splice(s,1),t.hp<=0){const h=t.type;return this.powerups.splice(e,1),h}break}}}return null}updateActive(i){for(const e in this.activePowerUps){if(e==="life")continue;const t=this.activePowerUps[e];t.remaining-=i*1e3,t.remaining<=0&&delete this.activePowerUps[e]}}hasActive(i){return i in this.activePowerUps}getRemainingTime(i){return i in this.activePowerUps?Math.max(0,this.activePowerUps[i].remaining):0}clear(){this.powerups=[],this.activePowerUps={},this.lastSpawnScore=0}}window.POWERUP_TYPES=POWERUP_TYPES,window.PowerUp=PowerUp,window.PowerUpManager=PowerUpManager;
